function gfFormsAddConditionalColumns(){var config={attributes:true,attributeFilter:["style"],childList:false,subtree:true};function callback(mutationList,observer){mutationList.forEach(function(mutation){if(mutation.type==="attributes"){if(mutation.target.parentElement.parentElement.className.search("gfmc-column")!==-1){CheckParentsChildrenDisplayValueAndHideParentIfNecessary(mutation.target.parentElement.parentElement,mutation.target.style.display)}}})}function CheckParentsChildrenDisplayValueAndHideParentIfNecessary(GFMCParent,targetDisplayValue){if(GFMCParent.firstChild.children.length===1){targetDisplayValue!="none"?ShowParent(GFMCParent):HideParent(GFMCParent)}else if(GFMCParent.firstChild.children.length>1){if(AreAllChildrenHidden(GFMCParent)){HideParent(GFMCParent)}else{ShowParent(GFMCParent)}}}function HideParent(node){node.style.display="none"}function ShowParent(node){node.style.removeProperty("display")}function AreAllChildrenHidden(node){let childrenHiddenFlag=!0;for(let child of node.firstChild.children){if(child.style!=='undefined'){child.style.display!=='none'?childrenHiddenFlag=!1:null}}
  return childrenHiddenFlag}var gravityFormPages=document.getElementsByClassName("gform_page");var observer=null;if(gravityFormPages.length>0){for(var i=0;i<gravityFormPages.length;i++){observer=new MutationObserver(callback);observer.observe(gravityFormPages[i],config)}}else{var gravityForm=document.querySelector(".gform_body");observer=new MutationObserver(callback);observer.observe(gravityForm,config)}}
